import { loadFont as loadSans } from "@remotion/google-fonts/HankenGrotesk";
import { loadFont as loadSerif } from "@remotion/google-fonts/Newsreader";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, interpolate, staticFile, useCurrentFrame } from "remotion";

// Dra. Monique Lopes Sabino · "Lítio é bateria?" · v3, teste em tela dividida. Vertical, 92,2 s.
// v3: mesma fala, cenas e lettering da v2; quando entra o motion a tela se divide (motion em cima, ela embaixo, filete areia
// na divisa) e a legenda passa a cobrir a fala inteira. O cartão final com a foto ocupa a tela toda.
// v2 (pedido): legenda em lettering embaixo, sem caixa, palavra por palavra; zoom de vai e volta nela a cada frase;
// transições suaves (desfoque + deslize curto) indo e voltando do vídeo; mais movimento nos objetos das cenas.
// O áudio é a fala dela (IMG_8068), só sem as pausas e sem as tomadas repetidas do convite final: public/monique/voz-corte.wav
// e o vídeo cortado igual (monique-corte.mp4). Tempos = tempo da fala no corte.
// Estilo da referência 01-evento (ela falando, intercalada com cenas desenhadas), na identidade do guia dela: editorial,
// calmo e acolhedor. Creme, petróleo, noite e terra; Newsreader nos títulos, ênfase em itálico colorido (terra no claro,
// areia no escuro); Hanken Grotesk em caixa alta espaçada nos rótulos. Sem brilho atrás do texto.

const { fontFamily: SERIF } = loadSerif("normal", { weights: ["400", "500", "600"], subsets: ["latin", "latin-ext"] });
loadSerif("italic", { weights: ["400", "500"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const MQ3_FPS = 30;
const END = 92.2;
export const MQ3_FRAMES = Math.round(END * MQ3_FPS);

const NOITE = "#14212B";
const PETROLEO = "#1B2D3A";
const TERRA = "#8C5A4A";
const AREIA = "#C8A98C";
const CREME = "#F5F1EB";
const TEXTO = "#1F2A33";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.3));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

// texto entra desfocado, parado no lugar; sai inteiro antes do próximo
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 18 + o * 14).toFixed(1)}px)` };
};

type Tok = { w: string; em: boolean; tail: string };
const toks = (s: string): Tok[] => {
  const out: Tok[] = [];
  s.split("*").forEach((p, i) => {
    // pontuação colada no fim do trecho em ênfase vira "cauda" da palavra anterior, sem espaço
    const lead = p.match(/^[,.?!:;]+/);
    if (lead && out.length && !p.startsWith(" ")) { out[out.length - 1].tail += lead[0]; p = p.slice(lead[0].length); }
    p.split(" ").filter(Boolean).forEach((w) => out.push({ w, em: i % 2 === 1, tail: "" }));
  });
  return out;
};
const RISE = Easing.bezier(0.22, 1.2, 0.36, 1);
const Words: React.FC<{ t: number; at: number; s: string; em: string; gap?: number; d?: number; i0?: number }> = ({ t, at, s, em, gap = 0.07, d = 0.55, i0 = 0 }) => (
  <>
    {toks(s).map((x, i) => {
      const a0 = at + (i0 + i) * gap;
      const e = interpolate(t, [a0, a0 + d], [0, 1], { ...cl, easing: RISE });
      return (
        <span key={i} style={{ display: "inline-block", overflow: "hidden", verticalAlign: "top", padding: "0.1em 0.12em 0.16em", margin: "-0.1em 0.02em -0.16em" }}>
          <span style={{ display: "inline-block", transform: `translateY(${((1 - e) * 115).toFixed(1)}%) rotate(${((1 - e) * 7).toFixed(2)}deg)`, transformOrigin: "0% 100%", fontStyle: x.em ? "italic" : undefined }}><span style={{ color: x.em ? em : undefined, fontSize: x.em ? "1.1em" : undefined, fontWeight: x.em ? 500 : undefined }}>{x.w}</span><span style={{ fontStyle: "normal" }}>{x.tail}</span></span>
        </span>
      );
    })}
  </>
);
const nWords = (s: string) => toks(s).length;
// flutuação leve dos objetos (nunca do texto)
const fl = (t: number, f: number, ph: number, amp: number) => Math.sin(t * f + ph) * amp;
// anéis que se abrem a partir de um ponto, quando algo se confirma
const Ripple: React.FC<{ t: number; at: number; size: number; c: string; n?: number }> = ({ t, at, size, c, n = 2 }) => (
  <>
    {[...Array(n)].map((_, i) => {
      const u = lin(t, at + i * 0.18, at + i * 0.18 + 1.0);
      return u <= 0 || u >= 1 ? null : <div key={i} style={{ position: "absolute", left: "50%", top: "50%", width: size, height: size, marginLeft: -size / 2, marginTop: -size / 2, borderRadius: "50%", border: `3px solid ${c}`, opacity: (1 - u) * 0.7, transform: `scale(${(1 + u * 0.9).toFixed(3)})` }} />;
    })}
  </>
);

type Ln = { w: string; size?: number };
const Title: React.FC<{ t: number; at: number; out?: number; top: number; lines: Ln[]; dark?: boolean; size?: number }> = ({ t, at, out, top, lines, dark, size = 104 }) =>
  out !== undefined && t > out + 0.2 ? null : (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", opacity: out === undefined ? 1 : 1 - lin(t, out, out + 0.2), filter: out === undefined ? undefined : `blur(${(lin(t, out, out + 0.2) * 14).toFixed(1)}px)` }}>
      {lines.map((l, i) => (
        <div key={i} style={{ fontFamily: SERIF, fontWeight: 400, fontSize: l.size ?? size, lineHeight: 1.08, letterSpacing: "-0.02em", color: dark ? CREME : TEXTO, whiteSpace: "nowrap" }}>
          <Words t={t} at={at} s={l.w} em={dark ? AREIA : TERRA} i0={lines.slice(0, i).reduce((n, x) => n + nWords(x.w), 0)} />
        </div>
      ))}
    </div>
  );

const Label: React.FC<{ t: number; at: number; out?: number; top: number; w: string; c: string; size?: number }> = ({ t, at, out, top, w, c, size = 34 }) =>
  out !== undefined && t > out + 0.2 ? null : (
    <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: SANS, fontWeight: 600, fontSize: size, letterSpacing: "0.3em", paddingLeft: "0.3em", color: c, ...blurIn(t, at, out) }}>{w}</div>
  );

// ───────── ícones de traço ─────────
const Capsula: React.FC<{ w: number; rot?: number; a?: string; b?: string; line?: string }> = ({ w, rot = -28, a = TERRA, b = CREME, line = TERRA }) => {
  const h = w * 0.4, r = h / 2;
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ transform: `rotate(${rot}deg)`, overflow: "visible" }}>
      <path d={`M${r} 0H${w / 2}V${h}H${r}A${r} ${r} 0 0 1 ${r} 0z`} fill={a} />
      <path d={`M${w / 2} 0H${w - r}A${r} ${r} 0 0 1 ${w - r} ${h}H${w / 2}z`} fill={b} />
      <rect x={2} y={2} width={w - 4} height={h - 4} rx={r - 2} fill="none" stroke={line} strokeWidth={5} />
    </svg>
  );
};
const Bateria: React.FC<{ s: number; c: string; fill: number }> = ({ s, c, fill }) => (
  <svg width={s} height={s * 0.56} viewBox="0 0 100 56" fill="none">
    <rect x={3} y={3} width={84} height={50} rx={10} stroke={c} strokeWidth={5} />
    <rect x={88} y={18} width={9} height={20} rx={3} fill={c} />
    {[0, 1, 2, 3].map((i) => <rect key={i} x={11 + i * 19} y={11} width={15} height={34} rx={4} fill={c} opacity={fill > i / 4 ? 1 : 0.12} />)}
  </svg>
);
const Bike: React.FC<{ s: number; c: string; p: number }> = ({ s, c, p }) => (
  <svg width={s} height={s * 0.62} viewBox="0 0 100 62" fill="none" stroke={c} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round">
    <g strokeDasharray={420} strokeDashoffset={420 * (1 - p)}>
      <circle cx={20} cy={42} r={17} /><circle cx={80} cy={42} r={17} />
      <path d="M20 42L38 14H66L80 42M38 14L52 42H20M52 42L66 14M34 8H44M62 8H72" />
    </g>
  </svg>
);
const Carro: React.FC<{ s: number; c: string; p: number }> = ({ s, c, p }) => (
  <svg width={s} height={s * 0.5} viewBox="0 0 100 50" fill="none" stroke={c} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round">
    <g strokeDasharray={360} strokeDashoffset={360 * (1 - p)}>
      <path d="M6 36V27Q6 22 12 21L26 18L37 7H68L80 19L91 21Q95 22 95 27V36H82M28 36H66M18 36H6" />
      <circle cx={23} cy={37} r={8} /><circle cx={74} cy={37} r={8} /><path d="M40 10V19H74" />
    </g>
  </svg>
);
const Check: React.FC<{ s: number; c: string; p: number; w?: number }> = ({ s, c, p, w = 3 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5" strokeDasharray={22} strokeDashoffset={22 * (1 - p)} /></svg>
);
const Play: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M8 5.5v13l10.5-6.5z" /></svg>
);
const Balao: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={c} strokeWidth={3.4} strokeLinejoin="round"><path d="M8 10h32a3 3 0 0 1 3 3v19a3 3 0 0 1-3 3H20l-9 7v-7H8a3 3 0 0 1-3-3V13a3 3 0 0 1 3-3z" /></svg>
);

// ───────── ela ─────────
type Cap = [number, string];
// a legenda agora cobre a fala inteira (nos trechos de motion ela fica na parte de baixo, sobre ela)
const CAPS: Cap[] = [
  [0.0, "Uma vez eu atendi"], [0.94, "uma *paciente*"], [1.46, "que, quando eu fui"], [2.92, "prescrever o *lítio*"], [4.0, "pra ela,"],
  [4.42, "que é um estabilizador"], [5.1, "de *humor*,"], [5.52, "a primeira pergunta"], [6.44, "que ela me fez foi:"], [7.38, "*Lítio?*"], [8.12, "Mas é aquele negócio"], [8.8, "que tem *bateria*"], [9.6, "de *bicicleta*?"],
  [11.84, "E eu falei assim:"], [12.66, "é, é mesmo."], [13.44, "Mas eu tomo isso?"], [14.98, "É *bateria*?"], [15.8, "Eu falei: ué,"], [16.4, "quando você tem *anemia*,"],
  [17.98, "você também não"], [18.56, "toma *ferro*?"], [19.36, "Que tem em *carro*?"], [20.5, "Aí ela parou pra pensar:"], [21.7, "Hum, é *verdade*."],
  [23.64, "Então, às vezes,"], [24.58, "a gente tem medo"], [25.66, "do *desconhecido*, né?"], [26.94, "O ferro, ninguém"], [27.88, "para pra pensar"], [28.34, "que o ferro tem em *carro*"],
  [29.44, "e que a gente está"], [30.0, "tomando, ingerindo,"], [31.3, "e que faz *bem* pra gente"], [32.74, "e que resolve a *anemia*,"], [34.26, "né?"],
  [34.72, "Mas quando a gente fala"], [35.9, "de uma coisa que a gente"], [36.98, "nunca ouviu falar,"], [38.08, "ou que a gente não conhece"], [39.32, "ninguém que faz uso,"],
  [40.66, "escuta *lítio*,"], [42.14, "assim como remédio,"], [43.34, "a gente tem aquele"], [44.38, "*medo* inicial"], [45.28, "daquilo que é"], [46.42, "*desconhecido* pra gente."], [47.48, "E isso é completamente"], [48.14, "*normal*."],
  [49.36, "Cabe a gente,"], [50.34, "do lado de cá,"], [51.24, "fazer essa *psicoeducação*"],
  [52.8, "e trazer"], [54.14, "de forma mais *leve*"], [55.44, "para o paciente,"], [56.12, "para que ele consiga"], [57.08, "dar *início* para o"], [58.06, "tratamento dele,"], [59.0, "sem que tenha *prejuízo*"], [60.82, "no quadro dele."],
  [61.64, "Porque às vezes"], [62.62, "o paciente fica"],
  [63.76, "*postergando*"], [65.24, "o tratamento"], [65.88, "por conta de *medo*"], [66.92, "de uma coisa que"], [67.62, "na verdade vai fazer"], [68.36, "*bem* pra ele,"], [68.92, "que é a *medicação*."],
  [69.66, "Quando tem *indicação*,"], [70.68, "obviamente."], [71.44, "Mas esse medo,"], [73.26, "eu acho que faz parte."], [75.42, "Pra gente mesmo,"], [76.86, "da área de saúde,"], [77.78, "nesse trabalho de"], [78.84, "*psicoeducação*,"],
  [79.6, "para que a gente"], [80.12, "quebre esses *estigmas*"], [81.22, "que ainda existem"], [82.26, "na *sociedade*."],
  [83.32, "E você, já tinha"], [84.04, "pensado sobre isso?"], [84.9, "Já tinha feito essa"], [85.74, "analogia do *lítio*"], [86.84, "com *bateria*?"],
  [87.56, "Tem medo de usar *lítio*?"], [88.94, "Me conta aqui"], [89.4, "nos *comentários*."],
];
const CAP_STOP = 90.25;
const capEnd = (i: number) => {
  const nx = CAPS[i + 1];
  return Math.min(CAP_STOP, nx && nx[0] - CAPS[i][0] < 2.2 ? nx[0] : CAPS[i][0] + 1.6);
};

// trechos com motion: a tela se divide, motion em cima e ela embaixo (cor de fundo de cada cena)
const MS: [number, number, string][] = [[4.42, 10.9, CREME], [17.95, 23.5, PETROLEO], [29.44, 34.66, TERRA], [40.6, 49.25, NOITE], [52.75, 61.6, CREME], [63.5, 69.62, NOITE], [79.55, 83.25, CREME], [87.5, END + 1, PETROLEO]];
const SPLIT_D = 0.6;
const splitAt = (t: number) => MS.reduce((v, [a, b]) => Math.max(v, interpolate(t, [a - SPLIT_D / 2, a + SPLIT_D / 2, b - SPLIT_D / 2, b + SPLIT_D / 2], [0, 1, 1, 0], { ...cl, easing: INOUT })), 0);
const FULL_AT = 90.05;   // o cartão final com a foto ocupa a tela toda
const fullAt = (t: number) => interpolate(t, [FULL_AT, FULL_AT + 0.6], [0, 1], { ...cl, easing: INOUT });

// zoom de vai e volta a cada duas frases, em todo o vídeo
const ZK = CAPS.map((c) => c[0]).filter((_, j) => j % 2 === 0);
const herZoom = (t: number) => {
  let idx = 0;
  ZK.forEach((x, j) => { if (t >= x) idx = j; });
  const tgt = (j: number) => (j % 2 === 0 ? 1 : 1.075);
  const p = interpolate(t, [ZK[idx], ZK[idx] + 0.9], [0, 1], { ...cl, easing: INOUT });
  const z = idx === 0 ? 1 : tgt(idx - 1) + (tgt(idx) - tgt(idx - 1)) * p;
  return z * interpolate(t, [0, 0.8], [1.28, 1.04], { ...cl, easing: OUT });
};

const Her: React.FC<{ t: number; sp: number; full: number }> = ({ t, sp, full }) => {
  const top = 960 * sp + 960 * full;
  const i = CAPS.findIndex((c, j) => t >= c[0] && t < capEnd(j));
  const c = i >= 0 ? CAPS[i] : null;
  const end = i >= 0 ? capEnd(i) : 0;
  const dy = 125 * sp;
  return (
    <AbsoluteFill style={{ background: NOITE, clipPath: `inset(${top.toFixed(1)}px 0 0 0)` }}>
      <AbsoluteFill style={{ transform: `translateY(${(520 * sp).toFixed(1)}px) scale(${herZoom(t).toFixed(4)})`, transformOrigin: "61% 33%" }}>
        <OffthreadVideo src={staticFile("monique/monique-corte.mp4")} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1080 + 200 * sp, bottom: 0, background: "linear-gradient(to bottom, rgba(14,18,22,0) 0%, rgba(14,18,22,0.62) 45%, rgba(14,18,22,0.72) 100%)" }} />
      {c ? (
        <>
          <div style={{ position: "absolute", left: 540 - 50, top: 1392 + dy, width: 100, height: 5, borderRadius: 2, background: AREIA, transform: `scaleX(${k(t, c[0], 0.5).toFixed(3)})`, opacity: 1 - lin(t, end - 0.1, end) }} />
          <div style={{ position: "absolute", left: 120, right: 120, top: 1426 + dy, textAlign: "center", fontFamily: SERIF, fontWeight: 600, fontSize: 108 - 8 * sp, lineHeight: 1.0, letterSpacing: "-0.015em", color: CREME, textShadow: "0 3px 16px rgba(0,0,0,0.4)", opacity: 1 - lin(t, end - 0.1, end), filter: `blur(${(lin(t, end - 0.1, end) * 10).toFixed(1)}px)` }}>
            <Words t={t} at={c[0]} s={c[1]} em={AREIA} d={0.42} gap={Math.min(0.08, ((end - c[0]) * 0.45) / nWords(c[1]))} />
          </div>
        </>
      ) : null}
    </AbsoluteFill>
  );
};

// câmera lenta de cada cena desenhada
const Cam: React.FC<{ t: number; a: number; b: number; bg: string; z?: [number, number]; children: React.ReactNode }> = ({ t, a, b, bg, z = [1.0, 1.05], children }) => (
  <AbsoluteFill style={{ background: bg }}>
    <AbsoluteFill style={{ transform: `scale(${(interpolate(t, [a, b], [z[0], z[0] + (z[1] - z[0]) * 2.4], { ...cl, easing: Easing.inOut(Easing.sin) }) * interpolate(t, [a, a + 0.7], [1.08, 1], { ...cl, easing: OUT })).toFixed(4)}) rotate(${interpolate(t, [a, b], [z[1] > z[0] ? -1.2 : 1.2, 0], cl).toFixed(3)}deg)` }}>{children}</AbsoluteFill>
  </AbsoluteFill>
);
const Center: React.FC<{ top: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", alignItems: "center", ...style }}>{children}</div>
);

// ───────── M1 · lítio, estabilizador de humor → bateria de bicicleta? (creme) ─────────
const M1: React.FC<{ t: number }> = ({ t }) => {
  const swap = 8.12;
  const capIn = pop(t, 4.6, 0.7);
  const capOut = lin(t, swap, swap + 0.3);
  const batIn = pop(t, 8.4, 0.6);
  return (
    <Cam t={t} a={4.42} b={10.9} bg={CREME} z={[1.06, 1.0]}>
      <Label t={t} at={4.58} out={swap - 0.1} top={560} w="ESTABILIZADOR DE HUMOR" c={TERRA} />
      <Title t={t} at={4.75} out={swap - 0.1} top={630} size={200} lines={[{ w: t >= 7.38 ? "*Lítio?*" : "Lítio" }]} />
      <Title t={t} at={9.0} top={600} size={120} lines={[{ w: "bateria de" }, { w: "*bicicleta?*" }]} />
      {t < swap + 0.35 ? (
        <Center top={1060} style={{ height: 520, opacity: Math.min(1, capIn * 2) * (1 - capOut), transform: `translateY(${((1 - capIn) * 260).toFixed(1)}px) rotate(${((1 - capIn) * -60 + 22 * lin(t, 4.6, swap)).toFixed(2)}deg) translateY(${fl(t, 2.2, 0, 16).toFixed(1)}px) scale(${(1 - 0.3 * capOut + 0.06 * interpolate(t, [7.38, 7.5, 7.8], [0, 1, 0], cl)).toFixed(3)})`, filter: `blur(${(capOut * 10).toFixed(1)}px)` }}>
          <Capsula w={660} />
        </Center>
      ) : null}
      {t >= swap ? (
        <Center top={1130} style={{ gap: 90, opacity: Math.min(1, batIn * 2) }}>
          <div style={{ transform: `scale(${(0.6 + 0.4 * batIn).toFixed(3)}) translateY(${fl(t, 2.4, 1, 12).toFixed(1)}px) rotate(${((1 - batIn) * -25).toFixed(2)}deg)` }}><Bateria s={360} c={TERRA} fill={t < 9.6 ? lin(t, 8.6, 9.6) : ((t - 9.6) * 1.4) % 1.25} /></div>
          <div style={{ transform: `translateX(${((1 - k(t, 9.12, 0.7)) * 320 - lin(t, 9.12, 10.9) * 40).toFixed(1)}px) translateY(${fl(t, 9, 0, 3).toFixed(1)}px)`, opacity: k(t, 9.12, 0.3) }}><Bike s={400} c={TEXTO} p={lin(t, 9.12, 10.0)} /></div>
        </Center>
      ) : null}
    </Cam>
  );
};

// ───────── M2 · lítio tem em bateria, ferro tem em carro: os dois são remédio (petróleo) ─────────
const Cartao: React.FC<{ t: number; at: number; x: number; nome: string; icon: React.ReactNode; rem: number }> = ({ t, at, x, nome, icon, rem }) => {
  const e = pop(t, at, 0.6);
  return (
