const SCALE = 0.66;          // cena desenhada reduzida para caber na metade de cima
const CENTER_Y = 1010;       // centro do conteúdo das cenas, em 1920
export const MoniqueV3: React.FC = () => {
  const t = useCurrentFrame() / MQ3_FPS;
  const sp = splitAt(t);
  const full = fullAt(t);
  const mi = MS.findIndex(([a, b]) => t >= a - SPLIT_D / 2 && t < b + SPLIT_D / 2);
  const scenes = [M1, M2, M3, M4, M5, M6, M7, M8];
  const Scene = mi >= 0 ? scenes[mi] : null;
  const H = 960 + 960 * full;
  const sc = SCALE + (1 - SCALE) * full;
  const ty = (480 - CENTER_Y * SCALE) * (1 - full);
  return (
    <AbsoluteFill style={{ background: NOITE }}>
      <Her t={t} sp={sp} full={full} />
      {Scene && sp > 0 ? (
        <>
          <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: H, overflow: "hidden", background: MS[mi][2], opacity: Math.min(1, sp * 1.4), transform: `translateY(${(-(1 - sp) * 260).toFixed(1)}px)`, filter: `blur(${((1 - sp) * 14).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `translateY(${ty.toFixed(1)}px) scale(${sc.toFixed(4)})`, transformOrigin: "50% 0%" }}>
