            </div>
          </div>
          <div style={{ position: "absolute", left: 0, width: 1080, top: H - 3, height: 6, background: AREIA, transform: `scaleX(${sp.toFixed(3)})`, opacity: 1 - full }} />
        </>
      ) : null}
    </AbsoluteFill>
  );
};

